#include <iostream>
#include <queue>
#include <vector>
using namespace std;

int main() {
    int n, m;
    cin >> n >> m;
    vector<vector<pair<int, int>>> graph(n + 1);
    vector<int> indegree(n + 1);
    for (int i = 0; i < m; ++i) {
        int u, v, w;
        cin >> u >> v >> w;
        graph[u].push_back({v, w});
        ++indegree[v];
    }
    queue<int> pending;
    vector<int> topo;
    for (int i = 1; i <= n; ++i) if (indegree[i] == 0) pending.push(i);
    while (!pending.empty()) {
        int v = pending.front();
        pending.pop();
        topo.push_back(v);
        for (auto [next, weight] : graph[v]) {
            if (--indegree[next] == 0) pending.push(next);
        }
    }
    const long long NEG = -(1LL << 60);
    vector<long long> dp(n + 1, NEG);
    if (!topo.empty()) dp[topo[0]] = 0;
    for (int vertex : topo) {
        if (dp[vertex] == NEG) continue;
        for (auto [next, weight] : graph[vertex])
            dp[next] = max(dp[next], dp[vertex] + weight);
    }
    for (int i = 1; i <= n; ++i) cout << dp[i] << ' ';
    return 0;
}
